import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { http, HttpResponse } from 'msw'
import { setupServer } from 'msw/node'
import { createApp } from '../src/app.mjs'
import { createPricingClient } from '../src/pricing-client.mjs'

const pricingApi = 'http://pricing.test'
const prices = { A: 10, B: 2.5, C: 0.3 }
const mock = setupServer(
  http.get(`${pricingApi}/prices/:sku`, ({ params }) => HttpResponse.json({ price: prices[params.sku] })),
)
let server, base

before(async () => {
  // the app under test is reached over real HTTP on localhost; anything else unhandled fails
  mock.listen({
    onUnhandledFrame(frame, print) {
      if (new URL(frame.request.url).hostname === '127.0.0.1') return
      print.error()
    },
  })
  server = createServer(createApp({ pricing: createPricingClient(pricingApi) }))
  await new Promise((r) => server.listen(0, '127.0.0.1', r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => { mock.close(); server.close() })

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const call = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order: 201, sequential string id, summed total', async () => {
  const items = [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 4 }]
  const r = await call(await post({ items }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.match(r.body.id, /^\d+$/)
  assert.deepEqual(r.body, { id: r.body.id, items, total: 30 })
  const second = await call(await post({ items }))
  assert.equal(second.body.id, String(Number(r.body.id) + 1))
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  const r = await call(await post({ items: [{ sku: 'A', qty: 10 }] }))
  assert.equal(r.body.total, 100)
})

test('POST /orders: total over 100 gets 10% off, then is floored', async () => {
  assert.equal((await call(await post({ items: [{ sku: 'A', qty: 11 }] }))).body.total, 99)
  // 101 * 0.9 = 90.9 -> 90
  assert.equal((await call(await post({ items: [{ sku: 'A', qty: 10 }, { sku: 'B', qty: 0.4 }] }))).body.total, 90)
})

test('POST /orders: fractional totals are floored (not rounded)', async () => {
  assert.equal((await call(await post({ items: [{ sku: 'C', qty: 9 }] }))).body.total, 2)
})

test('POST /orders: extra item fields are stored and echoed as sent', async () => {
  const items = [{ sku: 'A', qty: 1, note: 'x' }]
  assert.deepEqual((await call(await post({ items }))).body.items, items)
})

test('POST /orders: missing/empty/non-array items -> 400 items required', async () => {
  for (const body of [{}, { items: [] }, { items: 'A' }]) {
    const r = await call(await post(body))
    assert.deepEqual([r.status, r.body], [400, { error: 'items required' }])
  }
})

test('POST /orders: invalid JSON -> 400 items required; empty body too', async () => {
  assert.deepEqual(await call(await post(null, '{nope')).then((r) => [r.status, r.body]), [400, { error: 'items required' }])
  assert.deepEqual(await call(await post(null, '')).then((r) => [r.status, r.body]), [400, { error: 'items required' }])
})

test('POST /orders: unknown sku (pricing gives no price) -> 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - undefined price gives NaN, serialised as null, and the order is stored
  const r = await call(await post({ items: [{ sku: 'ZZZ', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders: negative quantity is accepted and yields a negative total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - no validation of qty
  const r = await call(await post({ items: [{ sku: 'A', qty: -3 }] }))
  assert.deepEqual([r.status, r.body.total], [201, -30])
})

test('GET /orders/:id returns a created order', async () => {
  const items = [{ sku: 'B', qty: 2 }]
  const created = (await call(await post({ items }))).body
  const r = await call(await fetch(`${base}/orders/${created.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created)
})

test('GET /orders/:id for unknown id -> 200 {error:"not found"}', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - a missing order answers 200, not 404
  const r = await call(await fetch(`${base}/orders/does-not-exist`))
  assert.deepEqual([r.status, r.body], [200, { error: 'not found' }])
})

test('unmatched routes and methods -> 404 no route', async () => {
  const cases = [['GET', '/orders'], ['GET', '/nothing'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/extra'], ['GET', '/orders/']]
  for (const [method, path] of cases) {
    const r = await call(await fetch(`${base}${path}`, { method }))
    assert.deepEqual([method, path, r.status, r.body], [method, path, 404, { error: 'no route' }])
  }
})
